import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { ClaimView } from '../claims/claims-api';

export const GRADES = ['A', 'B', 'C'] as const;
export type Grade = (typeof GRADES)[number];

/** A grade a person was given, in force from its from-date until their next grade. */
export interface GradeView {
  grade: Grade;
  /** The date the grade is in force from (yyyy-mm-dd), or null when it applies from the beginning of time. */
  from: string | null;
}

/** Of a person's grades, the one in force on a date: the one with the latest from-date on or before it. */
export function gradeOn(grades: readonly GradeView[], date: string): Grade | null {
  let inForce: GradeView | null = null;
  for (const g of grades) {
    if (g.from !== null && g.from > date) continue;
    if (inForce === null || (inForce.from ?? '') < (g.from ?? '')) inForce = g;
  }
  return inForce?.grade ?? null;
}

/** A hold put on a person, both days included. */
export interface HoldView {
  /** The date the hold starts (yyyy-mm-dd), or null when it holds from the beginning of time. */
  from: string | null;
  /** The date the hold ends (yyyy-mm-dd), or null when it has no end. */
  to: string | null;
}

/** Whether a date (yyyy-mm-dd) falls within one of the holds. */
export function heldOn(holds: readonly HoldView[], date: string): boolean {
  return holds.some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));
}

export interface PersonView {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the store answered. */
  grade: Grade;
  /** Every grade the person was given, the one from the beginning of time first, then by from-date. */
  grades: GradeView[];
  /** Bumped on each save; an edit is sent with the version its editor loaded. */
  version: number;
  /** True as soon as a retirement date is set, whatever the date. */
  retired: boolean;
  /** The date the person is retired from, or null while they are not retired. */
  retiredFrom: string | null;
  /** Whether the person has any hold, whatever its dates. */
  held: boolean;
  /** Every hold put on the person, by from-date: their open claims dated within one, unless a
   *  statement binds them, count in no live total. */
  holds: HoldView[];
  /** The ids of the other people on the sheet the person has named as patrons, in the order named. */
  patronIds: number[];
  /** Whether the signed-in user watches the person. */
  watched: boolean;
})
export class People {
  protected readonly session = inject(Session);
  private readonly api = inject(PeopleApi);
  private readonly claimsApi = inject(ClaimsApi);
  private readonly ratesApi = inject(RatesApi);
  private readonly statementsApi = inject(StatementsApi);
  private readonly periodsApi = inject(PeriodsApi);
  private readonly floor = inject(SheetFloor);
  private readonly cap = inject(SheetCap);
  private readonly latePct = inject(SheetLatePct);
  private readonly policyDate = inject(SheetPolicyDate);
  private readonly document = inject(DOCUMENT);
  /** What the late charges depend on now. */
  private readonly lateness = computed<Lateness>(() =>
    ({ today: this.session.sheet()?.today, latePct: (date: string) => this.latePct.pctOn(date),
      policyDate: this.policyDate.date() ?? this.session.sheet()?.today }));

  protected readonly grades = GRADES;
  protected readonly name = new FormControl('', { nonNullable: true });
  protected readonly grade = new FormControl<Grade>('A', { nonNullable: true });
  /** The date an edit gives the grade from; blank means the sheet's today. */
  protected readonly gradeFrom = new FormControl('', { nonNullable: true });
  /** The person's own terms, in whole days; blank means none. */
  protected readonly terms = new FormControl('', { nonNullable: true });
  protected readonly form = new FormGroup({ name: this.name, grade: this.grade, gradeFrom: this.gradeFrom,
    terms: this.terms });

  /** Everyone on the sheet, retired or not: their claims count in every total. */
  protected readonly people = signal<PersonView[]>([]);
  /** Whether retired people are listed; off when the screen opens, and kept as it is by loading a sheet. */
  protected readonly showRetired = signal(false);
  /** The people listed: the retired ones only while show retired is on. */
  protected readonly shownPeople = computed(() => this.people().filter((p) => this.showRetired() || !p.retired));
  /** The person being retired. */
  protected readonly retiring = signal<number | null>(null);
  /** The person a patron is being added to. */
  protected readonly addingPatron = signal<number | null>(null);
  /** The refusal of the last patron added on a person's row, shown on that row. */
  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
  /** The person a hold is being put on. */
  protected readonly holding = signal<number | null>(null);
  /** The holds of each person, by id. */
  private readonly holdsById = computed(() => new Map(this.people().map((p) => [p.id, p.holds])));
  /** The retirement date of each retired person, by id. */
  private readonly retiredFromById = computed(() => new Map(this.people().map((p) => [p.id, p.retiredFrom])));
  /** The sheet's claims, newest first. */
  protected readonly claims = signal<ClaimView[]>([]);
  private readonly claimsByPerson = computed(() => {
    const by = new Map<number, ClaimView[]>();
    for (const c of this.claims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
    return by;
  });
  private readonly centsByPerson = computed(() => {
    const by = new Map<number, number>();
    for (const c of this.claims()) if (this.countsLive(c)) by.set(c.personId, (by.get(c.personId) ?? 0) + cents(c.amount));
    return by;
  });
  protected readonly claimedTotal = computed(() => money(this.claims().reduce((t, c) => (this.countsLive(c) ? t + cents(c.amount) : t), 0)));
  /** The sheet's rates; a grade with no rate is left out. */
  protected readonly rates = signal<RateView[]>([]);
  private readonly ratesByGrade = computed(() => {
    const by = new Map<Grade, RateView[]>();
    for (const r of this.rates()) by.set(r.grade, [...(by.get(r.grade) ?? []), r]);
    return by;
  });
  /** Everyone's due-total added up, skipping the people whose due-total is n/a, trimmed. */
  protected readonly sheetDueTotal = computed(() => {
    const figures: number[] = [];
    for (const p of this.people()) {
      const due = this.dueCentsOf(p);
      if (due !== null) figures.push(due);
    }
    return money(trimmedSum(figures));
  });
  /** Each person's overdue claims that count, by person: how many, and the sum of their figures in
   *  cents, skipping those that are n/a. */
  private readonly overdueByPerson = computed(() => {
    const by = new Map<number, { count: number; cents: number }>();
    const byId = new Map(this.people().map((p) => [p.id, p]));
    const today = this.session.sheet()?.today;
    for (const c of this.claims()) {
      const person = byId.get(c.personId);
      if (person === undefined || !this.countsLive(c) || !isOverdue(c, today)) continue;
      const due = claimOwedCents(c, this.ratesOn(person, c.date), this.floor.centsOn(c.date), this.lateness(), this.claims());
      const was = by.get(c.personId) ?? { count: 0, cents: 0 };
      by.set(c.personId, { count: was.count + 1, cents: was.cents + (due ?? 0) });
    }
    return by;
  });
  /** Each person's open (PENDING included) claims that count, by person: the sum of their figures in
          <label [for]="'claim-reassign-to-' + c.id">Move to</label>
          <select #reassignTo [id]="'claim-reassign-to-' + c.id" data-testid="claim-reassign-to">
            <option value="">Choose a person</option>
            @for (o of people(); track o.id) {
              @if (o.id !== personId()) {
                <option [value]="o.id">{{ o.name }}</option>
              }
            }
          </select>
          <button type="button" data-testid="claim-reassign" (click)="reassign(c, reassignTo.value)"
            [attr.aria-label]="'Move claim of ' + c.amount + ' on ' + c.date + ' to another person'">Move</button>
          <button type="button" data-testid="claim-edit" (click)="edit(c)"
            [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
          @if (editingId() === c.id) {
            <button type="button" data-testid="claim-cancel" (click)="cancel()">Cancel</button>
          }
          @if (claimError()?.id === c.id) {
            <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
          }
        </li>
      }
    </ul>
  `,
})
export class PersonClaims {
  private readonly session = inject(Session);
  private readonly api = inject(ClaimsApi);
  private readonly editors = inject(ClaimEditors);
  private readonly floor = inject(SheetFloor);
  private readonly latePct = inject(SheetLatePct);
  private readonly policyDate = inject(SheetPolicyDate);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** The person's claims, newest first. */
  readonly claims = input.required<ClaimView[]>();
  /** Everyone on the sheet, whom a claim can be moved to. */
  readonly people = input.required<readonly { id: number; name: string }[]>();
  /** The sheet's rates, whatever their grades and from-dates. */
  readonly rates = input.required<RateView[]>();
  /** The person's grades, each from its from-date. */
  readonly grades = input.required<GradeView[]>();
  /** The sheet's periods in date order. */
  readonly periods = input.required<PeriodView[]>();
  /** The ids of the claims selected on the sheet. */
  readonly selected = input.required<ReadonlySet<number>>();
  /** A claim's checkbox ticked or cleared. */
  readonly selectedChange = output<{ id: number; on: boolean }>();
  readonly added = output<ClaimView>();
  readonly saved = output<ClaimView>();
  /** A claim whose status changed. */
  readonly changed = output<ClaimView>();
  /** A claim moved to another person. */
  readonly reassigned = output<ClaimView>();
  /** A claim split in two. */
  readonly split = output<SplitView>();

  protected readonly amount = new FormControl('', { nonNullable: true });
  protected readonly date = new FormControl('', { nonNullable: true });
  protected readonly note = new FormControl('', { nonNullable: true });
  protected readonly corrects = new FormControl('', { nonNullable: true });
  protected readonly form = new FormGroup({ amount: this.amount, date: this.date, note: this.note, corrects: this.corrects });

  /** The claim the editor has open, or null when the form adds a claim; it stays open while the sheet
   *  is re-loaded. */
  protected readonly editingId = computed(() => {
    const sheet = this.session.sheet();
    return sheet ? this.editors.editing(sheet.id, this.personId()) : null;
  });
  /** The claim whose values the form was last filled with. */
  private filledFor: number | null = null;
  /** The last edit button's open of the editor, settled once the store has answered it. */
  private opening: Promise<void> = Promise.resolve();
  protected readonly saving = signal(false);
  protected readonly error = signal('');
  /** The refusal of the last action taken on a claim's row, shown on that row. */
  protected readonly claimError = signal<{ id: number; message: string } | null>(null);

  constructor() {
    this.form.valueChanges.subscribe(() => {
      this.error.set('');
      // A refused save shown on the claim being edited belongs to the form too.
      if (this.editingId() !== null && this.claimError()?.id === this.editingId()) this.claimError.set(null);
    });
    // An editor left open when the sheet was re-loaded is filled again once its claim is shown.
    effect(() => {
      const id = this.editingId();
      if (id === null || id === this.filledFor) return;
      const claim = this.claims().find((c) => c.id === id);
      if (claim) this.fill(claim);
    });
  }

  /** What is due on the claim: the figure fixed when it was settled, else the figure its person's
   *  last statement bound it to, else at the rate in force on the claim's date of the person's grade
   *  in force on that date, and at least the sheet's floor, or n/a when the claim is dated before every rate of the grade;
   *  an open overdue claim has its late charge on top. */
  protected due(claim: ClaimView): string {
    const grade = gradeOn(this.grades(), claim.date);
    const due = claimOwedCents(claim, this.rates().filter((r) => r.grade === grade), this.floor.centsOn(claim.date),
      { today: this.session.sheet()?.today, latePct: (date: string) => this.latePct.pctOn(date),
        policyDate: this.policyDate.date() ?? this.session.sheet()?.today }, this.claims());
    return due === null ? 'n/a' : money(due);
  }

  /** Whether the claim is open and its due-by is before the sheet's today. */
  protected overdue(claim: ClaimView): boolean {
    return isOverdue(claim, this.session.sheet()?.today);
  }

  /** Whether the claim is OPEN and deferred until a date the sheet's today has not reached. */
  protected deferred(claim: ClaimView): boolean {
    return isDeferred(claim, this.session.sheet()?.today);
  }

  /** The name of the period whose dates contain the claim's due-by, or blank when none does. */
