  protected readonly sheetSettledOpen = computed(() => {
    let settled = 0;
    let open = 0;
    for (const p of this.people()) {
      const o = this.settledOpenByPerson().get(p.id);
      settled += o?.settled ?? 0;
      open += o?.open ?? 0;
